/**
 * Worker (any language) dials the relay and holds ONE bidi stream.
 * worker→relay carries results/liveness; relay→worker carries commands.
 */
export type SandboxWorkerService = typeof SandboxWorkerService;
export const SandboxWorkerService = {
  attach: {
    path: "/sandbox.v1.SandboxWorker/Attach",
    requestStream: true,
    responseStream: true,
    requestSerialize: (value: WorkerFrame) => Buffer.from(WorkerFrame.encode(value).finish()),
    requestDeserialize: (value: Buffer) => WorkerFrame.decode(value),
    responseSerialize: (value: ServerFrame) => Buffer.from(ServerFrame.encode(value).finish()),
    responseDeserialize: (value: Buffer) => ServerFrame.decode(value),
  },
} as const;

export interface SandboxWorkerServer extends UntypedServiceImplementation {
  attach: handleBidiStreamingCall<WorkerFrame, ServerFrame>;
}

export interface SandboxWorkerClient extends Client {
  attach(): ClientDuplexStream<WorkerFrame, ServerFrame>;
  attach(options: Partial<CallOptions>): ClientDuplexStream<WorkerFrame, ServerFrame>;
  attach(metadata: Metadata, options?: Partial<CallOptions>): ClientDuplexStream<WorkerFrame, ServerFrame>;
}

